mapper.select:
SELECT TTP.*,TS.REALNAME,TORG.ORGNAME,TASK.PLANID,PL.plannumber,PL.planname,RS.RISKNUMBER from TBL_TESTTASK_PROBLEMFIND TTP LEFT JOIN TBL_TESTTASK task on TTP.TESTTASKID=TASK.TESTTASKID LEFT JOIN TBL_RISK rs on TTP.RISKNUMBERID=RS.RISKID LEFT JOIN TBL_TESTPLAN pl on task.planid=pl.testplanid LEFT JOIN TBL_STAFF TS ON TS.STAFFID=TTP.REFORMSTAFFID LEFT JOIN TBL_ORGANIZATION TORG ON TORG.ORGID=TTP.MAINORG where 1=1 and TTP.status in (6)
AND TTP.DEFECTLEVEL LIKE concat(concat('%',#{queryParam.defectlevel}),'%')
AND TTP.problemtype LIKE concat(concat('%',#{queryParam.problemtype}),'%')
and TTP.ONEPROCESS LIKE concat(concat('%',#{queryParam.oneprocess}),'%')
and year(TTP.createtime) = #{queryParam.testYear}
and TTP.ZGSTATUS = #{queryParam.zgstatus}
${sql}
ORDER BY TTP.FINDID desc
